use serde::Serialize;

#[derive(Debug, Serialize)]
pub struct Invoice {
    pub customer_id: u64,
    pub amount: i64,
}

pub fn build_client() -> reqwest::Client {
    reqwest::Client::new()
}

pub async fn send_invoice(client: &reqwest::Client, invoice: &Invoice) -> reqwest::Result<()> {
    client
        .post("https://billing.internal/api/invoices")
        .json(invoice)
        .send()
        .await?;
    Ok(())
}

